#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# NUC wizard, part 2: from the base system of part 1 to ChargeOnSolar served
# over HTTPS, with deploys and nightly backups in place. Spec: #64, #73.
# Guide: docs/deployment/2-put-chargeonsolar-on-the-nuc.md.
#
# Runs on the NUC itself, after part 1 (setup-nuc.sh): sudo bash setup-nuc-2.sh
# Every stage first checks the machine and skips what is already in place, so
# a second run changes nothing. On purpose, one thing does change: the deploy
# and backup scripts are refreshed when main has a newer version of them.

USER_NAME="${SUDO_USER:-}"
USER_HOME=""
FROM_MAC="" # ~/from-mac: where the User copies files from the Mac

REPO_URL=https://github.com/roelnoort/ChargeOnSolar.git
APP_DIR=/srv/chargeonsolar
APP_ENV=$APP_DIR/.env
DATA_DIR=$APP_DIR/data
APP_UID=1000 # the image's `node` user, which writes the database
PROXY_DIR=/srv/proxy
PROXY_ENV=$PROXY_DIR/.env
TRANSIP_KEY=$PROXY_DIR/transip.key
PROXY_FILES=(compose.yaml Caddyfile Dockerfile .env.example)
DEPLOY_USER=deploy
DEPLOY_SCRIPT=/usr/local/bin/chargeonsolar-deploy
DEPLOY_KEY_OPTIONS="restrict,command=\"$DEPLOY_SCRIPT\""
BACKUP_SCRIPT=/usr/local/bin/chargeonsolar-backup
BACKUP_CRON=/etc/cron.d/chargeonsolar-backup
BACKUP_MOUNT=/backup

DONE=()
ALREADY=()
NEXT=()

already_done() {
  ALREADY+=("$1")
  printf '  %s✓ already done:%s nothing to change.\n' "$GREEN" "$RESET"
}
did() {
  DONE+=("$1")
  printf '  %s✓ done%s\n' "$GREEN" "$RESET"
}
# skip_stage "why": the stage gives up; the summary lists it as still to do.
skip_stage() {
  SKIPPED+=("$1")
  warn "skipped: $1"
  pause
}

pkg_installed() { [[ "$(dpkg-query -W -f='${Status}' "$1" 2>/dev/null)" == "install ok installed" ]]; }
apt_install() { DEBIAN_FRONTEND=noninteractive apt-get install -y -q "$@"; }
apt_update() { apt-get update -q; }

# file_is PATH CONTENT: PATH exists and holds exactly CONTENT.
file_is() { [[ -f "$1" && "$(cat "$1")" == "$2" ]]; }

# write_file PATH MODE CONTENT
write_file() {
  install -d -m 0755 "$(dirname "$1")"
  printf '%s\n' "$3" > "$1"
  chmod "$2" "$1"
  printf '  %s✓ wrote%s %s\n' "$GREEN" "$RESET" "$1"
}

# field_after WORD: the word after WORD in an `ip route` line on stdin.
field_after() { awk -v word="$1" '{ for (i = 1; i < NF; i++) if ($i == word) { print $(i + 1); exit } }'; }
nuc_address() { ip -4 route get 1.1.1.1 2>/dev/null | field_after src; }

in_group() { grep -qx "$2" < <(id -nG "$1" 2>/dev/null | tr ' ' '\n'); }

# private_to PATH USER: PATH is a file owned by USER that only USER can read.
private_to() { [[ -f "$1" && "$(stat -c '%U %a' "$1")" == "$2 600" ]]; }
make_private() {
  chown "$2:$2" "$1"
  chmod 600 "$1"
}

# env_value FILE KEY: KEY's value in the .env FILE; fails when it has none.
env_value() {
  local ENV_FILE="$1"
  _existing "$2"
}

deploy_home() { getent passwd "$DEPLOY_USER" | cut -d: -f6; }

# as_deploy CMD...: runs CMD as the deploy user, with its own HOME, because git
# and docker read their config from there and root's is closed to it.
as_deploy() { runuser -u "$DEPLOY_USER" -- env HOME="$(deploy_home)" "$@"; }

# from_main PATH prints the file at PATH in the clone's origin/main.
from_main() { as_deploy git -C "$APP_DIR" show "origin/main:$1"; }

# container_running PROJECT SERVICE, by compose's labels, so it needs no .env.
container_running() {
  [[ -n "$(docker ps -q --filter "label=com.docker.compose.project=$1" \
    --filter "label=com.docker.compose.service=$2" --filter status=running)" ]]
}

# copy_hint "path on the Mac" NAME shows how to copy a file into ~/from-mac.
copy_hint() {
  step "In a terminal on the Mac, in the ChargeOnSolar folder:"
  printf '\n      %sscp %s nuc:from-mac/%s%s\n\n' "$BOLD" "$1" "$2" "$RESET"
}

# take_from_mac NAME DEST OWNER moves ~/from-mac/NAME to DEST, private to
# OWNER. Fails when the User hasn't copied it there.
take_from_mac() {
  local source="${FROM_MAC:?}/${1:?}"
  [[ -f "$source" ]] || return 1
  install -m 600 -o "$3" -g "$3" "$source" "$2"
  rm -f "$source"
  printf '  %s✓ moved%s ~/from-mac/%s → %s\n' "$GREEN" "$RESET" "$1" "$2"
}

# ask_required KEY "Prompt": like ask, but asks again until KEY isn't empty.
ask_required() {
  while :; do
    ask "$1" "$2" || exit 1
    [[ -n "${!1}" ]] && return
    warn "This one can't be empty."
  done
}

# ask_if_missing KEY "Prompt": when ENV_FILE has no value for KEY, asks for one
# (it can't be empty) and writes it.
ask_if_missing() {
  [[ -n "$(_existing "$1" || true)" ]] && return
  ask_required "$1" "$2"
  write_env "$1" "${!1}"
}

# ── Stage 1: the deploy user ──────────────────────────────────────────────

# A password field of "*" matches no password, but sshd still takes the key;
# a locked account ("!") would refuse it.
deploy_user_ready() {
  getent passwd "$DEPLOY_USER" >/dev/null &&
    [[ "$(getent passwd "$DEPLOY_USER" | cut -d: -f7)" == /bin/bash ]] &&
    [[ "$(getent shadow "$DEPLOY_USER" | cut -d: -f2)" == '*' ]] &&
    in_group "$DEPLOY_USER" docker &&
    [[ "$(stat -c %U "$APP_DIR")" == "$DEPLOY_USER" ]]
}

setup_deploy_user() {
  if deploy_user_ready; then already_done "the $DEPLOY_USER user"; return; fi
  if ! getent group docker >/dev/null; then
    skip_stage "the $DEPLOY_USER user: install Docker with part 1 first, then re-run"
    return
  fi
  say "GitHub's Deploy button logs in to the NUC as the user '$DEPLOY_USER'. A later"
  say "stage makes sure its key can only run the deploy. It is in the docker group,"
  say "so it can build and start ChargeOnSolar, and it owns $APP_DIR,"
  say "so it can check out a new version there. It has no password."
  printf '\n'
  if getent passwd "$DEPLOY_USER" >/dev/null; then
    usermod -aG docker -s /bin/bash "$DEPLOY_USER"
  else
    useradd --create-home --shell /bin/bash --groups docker "$DEPLOY_USER"
  fi
  usermod -p '*' "$DEPLOY_USER"
  chown "$DEPLOY_USER:$DEPLOY_USER" "$APP_DIR"
  did "the $DEPLOY_USER user, in the docker group, owning $APP_DIR"
  pause
}

# ── Stage 2: ChargeOnSolar's code ─────────────────────────────────────────

is_clone() {
  [[ "$(as_deploy git -C "$APP_DIR" remote get-url origin 2>/dev/null)" == "$REPO_URL" ]]
}

# need_clone "what" skips the stage when stage 2 hasn't cloned the repo.
need_clone() {
  is_clone && return 0
  skip_stage "$1: needs ChargeOnSolar's code in $APP_DIR (stage 2) first"
  return 1
}

setup_clone() {
  if ! getent passwd "$DEPLOY_USER" >/dev/null; then
    skip_stage "ChargeOnSolar's code: needs the $DEPLOY_USER user (stage 1) first"
    return
  fi
  if is_clone; then
    # Only the remote refs change: the stages after this install scripts from main.
    as_deploy git -C "$APP_DIR" fetch --quiet origin ||
      warn "couldn't fetch from GitHub, so the next stages use main as last fetched."
    already_done "ChargeOnSolar's code in $APP_DIR"
    return
  fi
  if [[ -n "$(ls -A "$APP_DIR")" ]]; then
    skip_stage "ChargeOnSolar's code: $APP_DIR isn't empty, and isn't a clone of $REPO_URL owned by $DEPLOY_USER"
    return
  fi
  say "Cloning ChargeOnSolar from GitHub into $APP_DIR, as $DEPLOY_USER."
  say "The repo is public, so this needs no GitHub login."
  printf '\n'
  if ! as_deploy git clone --quiet "$REPO_URL" "$APP_DIR"; then
    skip_stage "ChargeOnSolar's code: the clone failed; check the internet connection and re-run"
    return
  fi
  did "ChargeOnSolar's code in $APP_DIR"
  pause
}

# ── Stage 3: ChargeOnSolar's .env ─────────────────────────────────────────

# The settings the server reads, as KEY|shown or hidden|prompt.
APP_SETTINGS='SMTP_HOST|shown|SMTP host (smtp.lettermint.co):
SMTP_PORT|shown|SMTP port (587):
SMTP_USER|shown|SMTP user (lettermint):
SMTP_PASSWORD|hidden|SMTP password:
MAIL_FROM|shown|Sender (ChargeOnSolar <noreply@your domain>):
ZAPTEC_USERNAME|shown|Zaptec username:
ZAPTEC_PASSWORD|hidden|Zaptec password:
MAIN_FUSE_A|shown|Main fuse in amps:
HOMEWIZARD_HOST|shown|HomeWizard P1 meter address:
HOMEWIZARD_TOKEN|hidden|HomeWizard token:
ENPHASE_API_KEY|hidden|Enphase API key:
ENPHASE_CLIENT_ID|hidden|Enphase client ID:
ENPHASE_CLIENT_SECRET|hidden|Enphase client secret:
ENPHASE_SYSTEM_ID|shown|Enphase system ID:'

token_key_valid() { [[ "$(env_value "$APP_ENV" ENPHASE_TOKEN_KEY)" =~ ^[0-9a-fA-F]{64}$ ]]; }

fill_app_env() {
  local ENV_FILE="$APP_ENV" key visibility prompt
  say "Type each value as the Mac's .env has it. Enter leaves a setting out."
  printf '\n'
  while IFS='|' read -r -u 3 key visibility prompt; do
    if [[ "$visibility" == hidden ]]; then
      ask_secret "$key" "$prompt" || exit 1
    else
      ask "$key" "$prompt" || exit 1
    fi
    if [[ -n "${!key}" ]]; then write_env "$key" "${!key}"; fi
  done 3<<<"$APP_SETTINGS"
  [[ -f "$APP_ENV" ]] || (umask 077 && : >"$APP_ENV")
}

place_app_env() {
  take_from_mac chargeonsolar.env "$APP_ENV" "$DEPLOY_USER" && return
  say "Easiest is to copy the Mac's .env, which the device and Lettermint wizards filled in:"
  copy_hint .env chargeonsolar.env
  if confirm "Copied it? (No: type the settings in here instead)"; then
    take_from_mac chargeonsolar.env "$APP_ENV" "$DEPLOY_USER" && return
    warn "There is no ~/from-mac/chargeonsolar.env, so type the settings in instead."
  fi
  fill_app_env
}

setup_app_env() {
  need_clone ".env" || return 0
  if private_to "$APP_ENV" "$DEPLOY_USER" && token_key_valid; then
    already_done "$APP_ENV"
    return
  fi
  say "ChargeOnSolar reads its settings and secrets from $APP_ENV."
  say "Only $DEPLOY_USER can read it (chmod 600), and this wizard never shows it."
  printf '\n'
  [[ -f "$APP_ENV" ]] || place_app_env
  if ! token_key_valid; then
    local ENV_FILE="$APP_ENV"
    write_env ENPHASE_TOKEN_KEY "$(openssl rand -hex 32)"
    note "A new key to encrypt the Enphase refresh token. Every backup keeps a copy."
  fi
  make_private "$APP_ENV" "$DEPLOY_USER"
  did "$APP_ENV, readable only by $DEPLOY_USER"
  pause
}

# ── Stage 4: the shared proxy ─────────────────────────────────────────────

proxy_env() { env_value "$PROXY_ENV" "$1"; }
is_private_key() { openssl pkey -in "$1" -noout 2>/dev/null; }
transip_key_valid() { is_private_key "$TRANSIP_KEY"; }

proxy_files_present() {
  local file
  for file in "${PROXY_FILES[@]}"; do [[ -f "$PROXY_DIR/$file" ]] || return 1; done
}
proxy_settings_complete() {
  transip_key_valid &&
    [[ -n "$(proxy_env DOMAIN)" && -n "$(proxy_env ACME_EMAIL)" && -n "$(proxy_env TRANSIP_LOGIN)" ]]
}
proxy_settings_private() { private_to "$PROXY_ENV" "$USER_NAME" && private_to "$TRANSIP_KEY" "$USER_NAME"; }
proxy_network_exists() { docker network inspect proxy >/dev/null 2>&1; }

# A file that differs from the repo's may hold the User's own edits, such as
# another project's site block, so it is never overwritten.
copy_proxy_files() {
  local file content
  for file in "${PROXY_FILES[@]}"; do
    content=$(from_main "deploy/proxy/$file") || { warn "couldn't read deploy/proxy/$file from main"; continue; }
    if [[ ! -f "$PROXY_DIR/$file" ]]; then
      write_file "$PROXY_DIR/$file" 0644 "$content"
      chown "$USER_NAME:$USER_NAME" "$PROXY_DIR/$file"
    elif ! file_is "$PROXY_DIR/$file" "$content"; then
      note "$PROXY_DIR/$file differs from main's deploy/proxy/$file: kept as it is."
    fi
  done
}

paste_transip_key() {
  local tmp line
  say "Paste the TransIP private key, then press Enter (input is hidden; it stops at the END line):"
  while :; do
    tmp=$(mktemp)
    while IFS= read -rs line || { rm -f "${tmp:?}"; exit 1; }; do
      printf '%s\n' "$line" >>"$tmp"
      [[ "$line" == -----END* ]] && break
    done
    if is_private_key "$tmp"; then
      install -m 600 -o "$USER_NAME" -g "$USER_NAME" "$tmp" "$TRANSIP_KEY"
      rm -f "${tmp:?}"
      printf '  %s✓ wrote%s the private key → %s\n' "$GREEN" "$RESET" "$TRANSIP_KEY"
      return
    fi
    rm -f "${tmp:?}"
    warn "That isn't a readable private key. Paste it again, including the BEGIN and END lines."
  done
}

place_proxy_settings() {
  local ENV_FILE="$PROXY_ENV"
  if [[ ! -f "$FROM_MAC/proxy.env" && ! -f "$FROM_MAC/transip.key" ]]; then
    say "The proxy needs the domain and the TransIP API key that"
    say "scripts/setup-transip.sh saved on the Mac (#22). Copy both:"
    copy_hint deploy/proxy/.env proxy.env
    copy_hint deploy/proxy/transip.key transip.key
    pause "Copied them? Press Enter. (Can't? Enter, then type them in here.)"
  fi
  take_from_mac proxy.env "$PROXY_ENV" "$USER_NAME" || true
  take_from_mac transip.key "$TRANSIP_KEY" "$USER_NAME" || true
  ask_if_missing DOMAIN "Domain registered at TransIP:"
  ask_if_missing ACME_EMAIL "Email for Let's Encrypt's certificate warnings:"
  ask_if_missing TRANSIP_LOGIN "TransIP account name (not your email address):"
  transip_key_valid || paste_transip_key
}

setup_proxy() {
  need_clone "the shared proxy" || return 0
  if proxy_files_present && proxy_settings_complete && proxy_settings_private &&
    proxy_network_exists && container_running proxy caddy; then
    copy_proxy_files
    already_done "the shared proxy in $PROXY_DIR"
    return
  fi
  say "The shared proxy (Caddy) serves every project on this home server over"
  say "HTTPS, with one wildcard certificate for *.<domain>. It lives in $PROXY_DIR,"
  say "is the only container that publishes ports, and deploys never touch it."
  printf '\n'
  copy_proxy_files
  proxy_settings_complete || place_proxy_settings
  make_private "$PROXY_ENV" "$USER_NAME"
  make_private "$TRANSIP_KEY" "$USER_NAME"
  if ! proxy_network_exists; then
    docker network create proxy >/dev/null
    printf '  %s✓ created%s the Docker network proxy\n' "$GREEN" "$RESET"
  fi
  say "Building and starting the proxy. The first build takes a few minutes."
  if ! docker compose -f "$PROXY_DIR/compose.yaml" up -d --build --force-recreate; then
    skip_stage "the shared proxy didn't start: see docker compose -f $PROXY_DIR/compose.yaml logs"
    return
  fi
  did "the shared proxy in $PROXY_DIR"
  pause
}

# ── Stage 5: deploys ──────────────────────────────────────────────────────

# script_current REPO_PATH DEST: DEST is root's executable copy of main's REPO_PATH.
script_current() {
  local content
  content=$(from_main "$1") || return 1
  file_is "$2" "$content" && [[ "$(stat -c '%U %a' "$2")" == "root 755" ]]
}
install_script() {
  local content
  content=$(from_main "$1") || { warn "couldn't read $1 from main"; return 1; }
  write_file "$2" 0755 "$content"
  chown root:root "$2"
}

deploy_keys_file() { printf '%s/.ssh/authorized_keys' "$(deploy_home)"; }

# Every key in the file carries the forced command, and there is at least one.
deploy_keys_restricted() {
  local file
  file=$(deploy_keys_file)
  [[ -f "$file" ]] && awk -v options="$DEPLOY_KEY_OPTIONS " '
    /^[[:space:]]*(#|$)/ { next }
    index($0, options) == 1 { restricted++; next }
    { other++ }
    END { exit !(restricted > 0 && other == 0) }' "$file"
}

valid_public_key() {
  [[ "$1" =~ ^(ssh-|ecdsa-|sk-) ]] && ssh-keygen -l -f - <<<"$1" >/dev/null 2>&1
}

# add_deploy_key: asks for the public key and makes it the deploy user's only
# key. Fails when the User skips it.
add_deploy_key() {
  local ENV_FILE=/dev/null home file
  say "Paste the deploy public key: the line starting with ssh-ed25519 that the"
  say "deploy wizard on the Mac (scripts/setup-deploy.sh) shows. Not made yet?"
  say "Press Enter to skip, and re-run this wizard once you have it."
  while :; do
    ask DEPLOY_PUBLIC_KEY "Deploy public key:" || return 1
    [[ -n "$DEPLOY_PUBLIC_KEY" ]] || return 1
    valid_public_key "$DEPLOY_PUBLIC_KEY" && break
    warn "That isn't an SSH public key. Copy the whole line, starting with ssh-ed25519."
  done
  home=$(deploy_home)
  file=$(deploy_keys_file)
  install -d -m 0700 -o "$DEPLOY_USER" -g "$DEPLOY_USER" "$home/.ssh"
  (umask 077 && printf '%s %s\n' "$DEPLOY_KEY_OPTIONS" "$DEPLOY_PUBLIC_KEY" >"$file")
  make_private "$file" "$DEPLOY_USER"
  printf '  %s✓ wrote%s %s\n' "$GREEN" "$RESET" "$file"
  note "  key $(ssh-keygen -l -f - <<<"$DEPLOY_PUBLIC_KEY" | cut -d' ' -f2), which can only run $DEPLOY_SCRIPT"
}

setup_deploys() {
  need_clone "deploys" || return 0
  local script_ok=0 key_ok=0
  script_current deploy/deploy.sh "$DEPLOY_SCRIPT" && script_ok=1
  deploy_keys_restricted && key_ok=1
  if ((script_ok && key_ok)); then already_done "the deploy script and key"; return; fi
  say "The Deploy button (#71) logs in as $DEPLOY_USER over Tailscale. Its key can"
  say "only run $DEPLOY_SCRIPT: a copy of main's deploy/deploy.sh,"
  say "outside the checkout, so a deploy can't change the script it is running."
  printf '\n'
  if ((!script_ok)) && ! install_script deploy/deploy.sh "$DEPLOY_SCRIPT"; then
    skip_stage "the deploy script: re-run once $APP_DIR can fetch main"
    return
  fi
  if ((!key_ok)) && ! add_deploy_key; then
    ((script_ok)) || DONE+=("$DEPLOY_SCRIPT, from main")
    skip_stage "the deploy key: re-run this wizard once the deploy wizard (scripts/setup-deploy.sh) has made it"
    return
  fi
  did "the deploy script $DEPLOY_SCRIPT, and a key that can only run it"
  pause
}

# ── Stage 6: the nightly backup ───────────────────────────────────────────

BACKUP_CRON_CONTENT="# Written by setup-nuc-2.sh (ChargeOnSolar, #73): the nightly database backup.
# It runs as root: .env is private to $DEPLOY_USER, and SQLite must write next to
# the database, which belongs to uid $APP_UID.
# Its output goes to the journal: journalctl -t chargeonsolar-backup
SHELL=/bin/bash
PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
0 3 * * * root $BACKUP_SCRIPT 2>&1 | logger -t chargeonsolar-backup"

setup_backup() {
  need_clone "the nightly backup" || return 0
  local script_ok=0 cron_ok=0
  script_current deploy/backup.sh "$BACKUP_SCRIPT" && script_ok=1
  file_is "$BACKUP_CRON" "$BACKUP_CRON_CONTENT" && cron_ok=1
  if ((script_ok && cron_ok)); then
    already_done "the nightly backup at 03:00"
  else
    say "Every night at 03:00, $BACKUP_SCRIPT, a copy of main's"
    say "deploy/backup.sh, backs up the database and .env to $BACKUP_MOUNT/chargeonsolar."
    say "It keeps the last 14 nights, and the first backup of each month for a year."
    printf '\n'
    if ((!script_ok)) && ! install_script deploy/backup.sh "$BACKUP_SCRIPT"; then
      skip_stage "the backup script: re-run once $APP_DIR can fetch main"
      return
    fi
    ((cron_ok)) || write_file "$BACKUP_CRON" 0644 "$BACKUP_CRON_CONTENT"
    did "the nightly backup at 03:00, to $BACKUP_MOUNT/chargeonsolar"
  fi
  if ! findmnt -n --mountpoint "$BACKUP_MOUNT" >/dev/null; then
    warn "$BACKUP_MOUNT isn't mounted, so the backup refuses to run: see part 1's backup disk stage."
  fi
  ((script_ok && cron_ok)) || pause
}

# ── Stage 7: start ChargeOnSolar ──────────────────────────────────────────

data_dir_ready() { [[ -d "$DATA_DIR" && "$(stat -c %u:%g "$DATA_DIR")" == "$APP_UID:$APP_UID" ]]; }

# https_ok DOMAIN: ChargeOnSolar answers through the proxy with a certificate
# curl trusts. Straight to this machine, so the router's DNS can't get in the way.
https_ok() {
  curl -fsS -o /dev/null --max-time 10 --resolve "charge.$1:443:127.0.0.1" "https://charge.$1/"
}

# The first wildcard certificate takes a minute or two: DNS has to spread.
wait_for_https() {
  local tries
  for ((tries = 0; tries < 60; tries++)); do
    https_ok "$1" 2>/dev/null && { printf '\n'; return 0; }
    printf '.'
    sleep 5
  done
  printf '\n'
  https_ok "$1"
}

check_dns() {
  local resolved here
  resolved=$(getent ahostsv4 "charge.$1" | awk 'NR == 1 { print $1 }') || true
  here=$(nuc_address) || true
  if [[ -z "$resolved" ]]; then
    warn "charge.$1 doesn't resolve here: check the A record 'charge' at TransIP (#22)."
  elif [[ -n "$here" && "$resolved" != "$here" ]]; then
    warn "charge.$1 points to $resolved, but the NUC is $here: fix the A record at TransIP."
  else
    printf '  %s✓%s charge.%s → %s\n' "$GREEN" "$RESET" "$1" "$resolved"
  fi
}

setup_start() {
  need_clone "starting ChargeOnSolar" || return 0
  local domain
  domain=$(proxy_env DOMAIN || true)
  if [[ -z "$domain" || ! -f "$APP_ENV" ]]; then
    skip_stage "starting ChargeOnSolar: needs .env (stage 3) and the proxy (stage 4) first"
    return
  fi
  if data_dir_ready && container_running chargeonsolar chargeonsolar && https_ok "$domain" 2>/dev/null; then
    already_done "ChargeOnSolar at https://charge.$domain"
    return
  fi
  say "Starting ChargeOnSolar from $APP_DIR, the way a deploy does."
  printf '\n'
  if ! data_dir_ready; then
    install -d -m 0755 "$DATA_DIR"
    chown "$APP_UID:$APP_UID" "$DATA_DIR"
    printf '  %s✓ created%s %s, owned by uid %s (the app in the container)\n' "$GREEN" "$RESET" "$DATA_DIR" "$APP_UID"
  fi
  if ! container_running chargeonsolar chargeonsolar; then
    say "Building the image takes a few minutes the first time."
    if ! as_deploy docker compose -f "$APP_DIR/compose.yaml" up -d --build; then
      skip_stage "starting ChargeOnSolar: the build or start failed (see above)"
      return
    fi
  fi
  say "Waiting for https://charge.$domain to answer with a valid certificate."
  say "The first certificate can take a few minutes."
  if ! wait_for_https "$domain"; then
    note "See what the proxy says: docker compose -f $PROXY_DIR/compose.yaml logs caddy"
    skip_stage "https://charge.$domain didn't answer with a valid certificate; re-run to check again"
    return
  fi
  printf '  %s✓%s https://charge.%s answers, with a valid certificate\n' "$GREEN" "$RESET" "$domain"
  check_dns "$domain"
  did "ChargeOnSolar at https://charge.$domain"
  pause
}

# ── Before the stages ─────────────────────────────────────────────────────

preflight() {
  if (( EUID != 0 )); then
    echo "Run this wizard with sudo: sudo bash $0" >&2
    exit 1
  fi
  if [[ -z "$USER_NAME" || "$USER_NAME" == root ]]; then
    echo "Run it with sudo from your own account (not as root), so it knows who you are." >&2
    exit 1
  fi
  USER_HOME=$(getent passwd "$USER_NAME" | cut -d: -f6)
  # shellcheck source=/dev/null
  if [[ "$(. /etc/os-release && printf '%s' "$ID")" != ubuntu ]]; then
    echo "This wizard is for Ubuntu Server 26.04." >&2
    exit 1
  fi
  if ! command -v docker >/dev/null 2>&1 || [[ ! -d "$APP_DIR" || ! -d "$PROXY_DIR" ]]; then
    echo "Run part 1 of the NUC wizard first: sudo bash setup-nuc.sh" >&2
    exit 1
  fi

  local tools=(git openssl sqlite3 curl ca-certificates) missing=() pkg
  for pkg in "${tools[@]}"; do pkg_installed "$pkg" || missing+=("$pkg"); done
  command -v cron >/dev/null 2>&1 || missing+=(cron)
  if (( ${#missing[@]} )); then
    echo "Installing what this wizard needs first: ${missing[*]}"
    if ! { apt_update && apt_install "${missing[@]}"; }; then
      echo "Couldn't install them. Check the internet connection and run again." >&2
      exit 1
    fi
  fi

  FROM_MAC=$USER_HOME/from-mac
  install -d -m 0700 -o "$USER_NAME" -g "$USER_NAME" "$FROM_MAC"
  # The deploy user can't read the home folder sudo was started from.
  cd /
}

summary() {
  WRITTEN_ENV=() # finish would name one .env, but this wizard writes two
  finish
  local line domain
  if (( ${#DONE[@]} )); then
    say "${BOLD}Done this run:${RESET}"
    for line in "${DONE[@]}"; do note "  - $line"; done
    printf '\n'
  fi
  if (( ${#ALREADY[@]} )); then
    say "${BOLD}Already done, skipped:${RESET}"
    for line in "${ALREADY[@]}"; do note "  - $line"; done
    printf '\n'
  fi
  domain=$(proxy_env DOMAIN 2>/dev/null || true)
  [[ -n "$domain" ]] && NEXT+=("Open https://charge.$domain on a phone or laptop at home.")
  NEXT+=("Chapter 3: the deploy wizard on the Mac (scripts/setup-deploy.sh) sets up Tailscale and GitHub for the Deploy button.")
  say "${BOLD}Next:${RESET}"
  for line in "${NEXT[@]}"; do note "  - $line"; done
  printf '\n'
}

run_wizard() {

TOTAL_STAGES=7

preflight

banner "NUC setup, part 2: ChargeOnSolar, the proxy, deploys and backups"

stage "The deploy user"
setup_deploy_user

stage "ChargeOnSolar's code"
setup_clone

stage "ChargeOnSolar's settings (.env)"
setup_app_env

stage "The shared HTTPS proxy"
setup_proxy

stage "Deploys from GitHub"
setup_deploys

stage "Nightly backup"
setup_backup

stage "Start ChargeOnSolar"
setup_start

summary
}

run_wizard "$@"; exit
